initJs:
function(container, apiUrl, tables) {
  const tbody = container.querySelector("#inventory-tbody");
  const storeSelect = container.querySelector("#store-select");
  const categoryFilter = container.querySelector("#category-filter");
  const productNameSearch = container.querySelector("#product-name-search");
  const productCodeSearch = container.querySelector("#product-code-search");
  const stockStatusFilter = container.querySelector("#stock-status-filter");
  const errorMessage = container.querySelector("#error-message");
  const noResultsMessage = container.querySelector("#no-results-message");

  let allInventoryData = [];
  let storeData = [];
  let productData = [];

  // 在庫状況を判定する関数
  function getStockStatus(currentStock, safetyStock) {
    if (currentStock === 0) return 'shortage';
    if (currentStock < safetyStock) return 'shortage';
    if (currentStock > safetyStock * 2) return 'excess';
    return 'normal';
  }

  // 在庫状況のラベルを取得する関数
  function getStockStatusLabel(status) {
    switch(status) {
      case 'normal': return '適正';
      case 'shortage': return '不足';
      case 'excess': return '過剰';
      default: return '適正';
    }
  }

  // 在庫一覧を描画する関数
  function renderInventory(inventoryList) {
    if (!inventoryList || inventoryList.length === 0) {
      tbody.innerHTML = '';
      noResultsMessage.classList.remove('hidden');
      return;
    }

    noResultsMessage.classList.add('hidden');

    tbody.innerHTML = inventoryList.map(item => {
      const product = productData.find(p => p.商品ID === item.商品ID) || {};
      const stockStatus = getStockStatus(item.現在在庫数 || 0, item.安全在庫数 || 0);
      const statusLabel = getStockStatusLabel(stockStatus);
      const stockClass = item.現在在庫数 === 0 ? 'stock-zero' : '';

      return `
        <tr data-id="${item.在庫ID || item.商品ID}">
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td class="${stockClass}">${item.現在在庫数 || 0}</td>
          <td>${item.安全在庫数 || 0}</td>
          <td><span class="stock-status ${stockStatus}">${statusLabel}</span></td>
          <td>${item.更新日時 ? new Date(item.更新日時).toLocaleString('ja-JP') : ''}</td>
        </tr>
      `;
    }).join('');
  }

  // 店舗選択肢を設定する関数
  function populateStoreOptions() {
    if (storeData.length > 0) {
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
        storeData.map(store => `<option value="${store.店舗ID}">${store.店舗名}</option>`).join('');
    }
  }

  // エラーメッセージを表示する関数
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.classList.remove('hidden');
    setTimeout(() => {
      errorMessage.classList.add('hidden');
    }, 5000);
  }

  // バリデーション関数
  function validateSearchInputs() {
    const storeId = storeSelect.value;
    const productCode = productCodeSearch.value.trim();
    const productName = productNameSearch.value.trim();

    if (!storeId) {
      showError('店舗を選択してください');
      return false;
    }

    // 商品コードの数値チェック（入力がある場合のみ）
    if (productCode && !/^\d+$/.test(productCode)) {
      showError('商品コードは数値で入力してください');
      return false;
    }

    // 特殊文字チェック
    const dangerousChars = /<script|javascript:|on\w+\s*=|'|"|;|DROP|SELECT|INSERT|UPDATE|DELETE/i;
    if (dangerousChars.test(productName) || dangerousChars.test(productCode)) {
      showError('不正な文字が含まれています');
      return false;
    }

    // 最大文字数チェック
    if (productName.length > 255) {
      showError('商品名は255文字以内で入力してください');
      return false;
    }

    if (productCode.length > 20) {
      showError('商品コードは20桁以内で入力してください');
      return false;
    }

    return true;
  }

  // 検索フィルタリング関数
  function filterInventory() {
    if (!validateSearchInputs()) {
      return;
    }

    const storeId = storeSelect.value;
    const category = categoryFilter.value;
    const productName = productNameSearch.value.trim().toLowerCase();
    const productCode = productCodeSearch.value.trim();
    const stockStatus = stockStatusFilter.value;

    let filtered = allInventoryData.filter(item => {
      // 店舗フィルタ
      if (storeId && item.店舗ID !== storeId) return false;

      const product = productData.find(p => p.商品ID === item.商品ID) || {};

      // カテゴリフィルタ
      if (category && product.商品カテゴリ !== category) return false;

      // 商品名検索
      if (productName && !product.商品名?.toLowerCase().includes(productName)) return false;

      // 商品コード検索
      if (productCode && product.商品コード !== productCode) return false;

      // 在庫状況フィルタ
      if (stockStatus) {
        const currentStatus = getStockStatus(item.現在在庫数 || 0, item.安全在庫数 || 0);
        const statusLabel = getStockStatusLabel(currentStatus);
        if (statusLabel !== stockStatus) return false;
      }

      return true;
    });

    renderInventory(filtered);
  }

  // 検索条件クリア関数
  function clearSearchConditions() {
    storeSelect.value = '';
    categoryFilter.value = '';
    productNameSearch.value = '';
    productCodeSearch.value = '';
    stockStatusFilter.value = '';
    errorMessage.classList.add('hidden');
    noResultsMessage.classList.add('hidden');
    tbody.innerHTML = '';
  }

  // CSVエクスポート関数
  function exportToCSV() {
    const storeId = storeSelect.value;
    if (!storeId) {
      showError('店舗を選択してからエクスポートしてください');
      return;
    }

    const filtered = allInventoryData.filter(item => item.店舗ID === storeId);

    const headers = ['商品コード', '商品名', '現在在庫数', '安全在庫数', '在庫状況', '最終更新日時'];
    const csvContent = [
      '\uFEFF' + headers.join(','),
      ...filtered.map(item => {
        const product = productData.find(p => p.商品ID === item.商品ID) || {};
        const stockStatus = getStockStatus(item.現在在庫数 || 0, item.安全在庫数 || 0);
        const statusLabel = getStockStatusLabel(stockStatus);
        const updateTime = item.更新日時 ? new Date(item.更新日時).toLocaleString('ja-JP') : '';

        return [
          `"${product.商品コード || ''}"`,
          `"${product.商品名 || ''}"`,
          item.現在在庫数 || 0,
          item.安全在庫数 || 0,
          `"${statusLabel}"`,
          `"${updateTime}"`
        ].join(',');
      })
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `在庫一覧_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      // 店舗データ読み込み
      const stores = await window.aivicApi.list(1); // 店舗マスタ
      if (stores) {
        storeData = stores.filter(store => store.有効フラグ);
        populateStoreOptions();
      }

      // 商品データ読み込み
      const products = await window.aivicApi.list(2); // 商品マスタ
      if (products) {
        productData = products.filter(product => product.有効フラグ);
      }

      // 在庫データの生成（実際のシステムでは在庫テーブルから取得）
      // ここでは商品マスタから在庫データを生成
      if (productData.length > 0 && storeData.length > 0) {
        allInventoryData = [];
        storeData.forEach(store => {
          productData.forEach(product => {
            const currentStock = Math.floor(Math.random() * 200);
            const safetyStock = Math.floor(Math.random() * 50) + 10;

            allInventoryData.push({
              在庫ID: `${store.店舗ID}_${product.商品ID}`,
              店舗ID: store.店舗ID,
              商品ID: product.商品ID,
              現在在庫数: currentStock,
              安全在庫数: safetyStock,
              更新日時: new Date().toISOString()
            });
          });
        });
      }

    } catch (error) {
      console.error('初期データ読み込みエラー:', error);
      showError('データの読み込みに失敗しました');
    }
  }

  // イベントリスナー設定
  container.querySelector("#btn-search").addEventListener("click", filterInventory);

  container.querySelector("#btn-clear").addEventListener("click", clearSearchConditions);

  container.querySelector("#btn-export").addEventListener("click", exportToCSV);

  // Enter キーでの検索
  [productNameSearch, productCodeSearch].forEach(input => {
    input.addEventListener("keypress", (e) => {
      if (e.key === "Enter") {
        filterInventory();
      }
    });
  });

  // 初期データ読み込み実行
  loadInitialData();
}
